                        plt.plot(dias[indices_no_cero_energy], valor_energy[indices_no_cero_energy], 'o', label='Energy')
                        plt.plot(dias[indices_no_cero_energy], y_filtered4[indices_no_cero_energy], label='Envelope', color='red')
