                            plt.plot(np.array(tiempos)[indices_no_cero], entropia_shannon[indices_no_cero], "ob", mfc="r", mec = "r", label='ShannonEntropy: Points per hour -> 5 min')
                            plt.xlabel('Date', fontfamily="serif", fontweight='bold', color ="red", fontsize=18)
